package cn.binbin.crm;

import jakarta.validation.Valid;
import jakarta.validation.constraints.*;
import java.time.Instant;
import java.util.*;
import org.springframework.stereotype.Service;
import static cn.binbin.crm.TradeService.*;

/** No model tools: two typed commands, edited and confirmed by the current human. */
@Service
public class AiProposalService {
 public record DraftInput(@Valid BusinessService.LeadCreate lead,@Valid SalesService.ActivityCreate activity,@Min(0) long expectedVersion){}
 public record ConfirmInput(@NotBlank @Size(max=100) String confirmationToken,@Min(0) long expectedVersion){}
 final P3Base b;final AiService ai;final AiScenarioService scenarios;final AiQualityService quality;final BusinessService business;final SalesService sales;
 public AiProposalService(P3Base b,AiService ai,AiScenarioService scenarios,AiQualityService quality,BusinessService business,SalesService sales){this.b=b;this.ai=ai;this.scenarios=scenarios;this.quality=quality;this.business=business;this.sales=sales;}
 private AuthService.Actor actor(AuthService.Session s){var a=b.auth.actor(s);if(a.supportGrantId()!=null||!a.p4Access().aiUse())throw ApiError.forbidden("当前成员没有 AI 操作权限");if(!a.tenant().subscriptionEnd().isAfter(Instant.now()))throw ApiError.forbidden("订阅到期，不能保存业务草稿");b.context(a.tenant().id());b.db.queryForObject("SELECT id FROM sys_tenant WHERE id=:tenant FOR UPDATE",map("tenant",a.tenant().id()),UUID.class);return a;}
 private Map<String,Object> eligible(AuthService.Session s,AuthService.Actor a,UUID runId){var run=ai.readRun(s,runId);if(!a.tenant().memberId().equals(run.get("memberId")))throw ApiError.forbidden("只能保存自己生成的业务草稿");if(run.get("accessHash")==null)throw ApiError.conflict("此结果缺少权限快照，请重新生成草稿");if(!"SUCCEEDED".equals(run.get("status")))throw ApiError.conflict("请先完成 AI 生成");String state=String.valueOf(run.get("qualityStatus"));if("REJECTED".equals(run.get("reviewStatus"))||!(state.equals("PASS")||state.equals("REVIEW")&&"ACCEPTED".equals(run.get("reviewStatus"))))throw ApiError.conflict("此草稿未通过质量检查；待复核结果需由主管确认后使用");String task=String.valueOf(run.get("taskType"));if(AiScenarioService.task(task).action().isEmpty())throw ApiError.bad("此场景不支持业务写入");if(!quality.current(s,task,run))throw ApiError.conflict("提示词或企业策略已变化，请重新生成草稿");if(!scenarios.sourceHash(s,task,(UUID)run.get("entityId")).equals(run.get("sourceHash")))throw ApiError.conflict("来源业务资料已变化，请重新生成并确认");return run;}
 private Map<String,Object> proposal(AuthService.Actor a,UUID id){return b.one("SELECT *,token_hash AS confirmation_hash FROM crm_ai_proposal WHERE tenant_id=:tenant AND member_id=:member AND id=:id FOR UPDATE",map("tenant",a.tenant().id(),"member",a.tenant().memberId(),"id",id));}
 private Object payload(Map<String,Object> run,AuthService.Actor a,DraftInput i){String task=String.valueOf(run.get("taskType"));if(task.equals("NEW_LEAD")){if(i.lead()==null||i.activity()!=null)throw ApiError.bad("请完整填写线索草稿");if(!a.tenant().memberId().equals(i.lead().ownerMemberId()))throw ApiError.bad("AI 新建线索须归属当前成员，之后可按业务权限转交");return i.lead();}if(i.activity()==null||i.lead()!=null||!run.get("entityId").equals(i.activity().customerId()))throw ApiError.bad("跟进草稿只能保存到本次来源客户");return i.activity();}
 public Object prepare(AuthService.Session s,UUID runId,DraftInput i,UUID trace){return b.tx.execute(st->{var a=actor(s);var run=eligible(s,a,runId);Object body=payload(run,a,i);String token=Crypto.token(),action=AiScenarioService.task(String.valueOf(run.get("taskType"))).action();var prior=b.rows("SELECT * FROM crm_ai_proposal WHERE tenant_id=:tenant AND run_id=:run AND member_id=:member FOR UPDATE",map("tenant",a.tenant().id(),"run",runId,"member",a.tenant().memberId()));UUID id=prior.isEmpty()?UUID.randomUUID():(UUID)prior.getFirst().get("id");long version=prior.isEmpty()?0:number(prior.getFirst(),"version");if(!prior.isEmpty()&&(!"DRAFT".equals(prior.getFirst().get("status"))||version!=i.expectedVersion()))throw ApiError.conflict("该草稿已保存、取消或被修改，请刷新");Instant expires=Instant.now().plusSeconds(300);var p=map("id",id,"tenant",a.tenant().id(),"run",runId,"member",a.tenant().memberId(),"action",action,"payload",b.json(body),"token",Crypto.hash(token),"source",run.get("sourceHash"),"expires",java.sql.Timestamp.from(expires));b.db.update("INSERT INTO crm_ai_proposal(id,tenant_id,run_id,member_id,action,payload,token_hash,source_hash,expires_at) VALUES(:id,:tenant,:run,:member,:action,cast(:payload AS jsonb),:token,:source,:expires) ON CONFLICT(tenant_id,run_id,member_id) DO UPDATE SET payload=excluded.payload,token_hash=excluded.token_hash,source_hash=excluded.source_hash,expires_at=excluded.expires_at,version=crm_ai_proposal.version+1",p);b.audit(a,"AI_PROPOSAL_PREPARED","AI_PROPOSAL",id,prior.isEmpty()?0:version+1,trace);return map("id",id,"version",prior.isEmpty()?0:version+1,"action",action,"payload",body,"confirmationToken",token,"expiresAt",expires,"notice","请核对所有字段。确认后才写入业务系统，同一生成记录仅保存一次。");});}
 private <T> T decode(Object payload,Class<T> type){try{return payload instanceof Map?b.data.json.convertValue(payload,type):b.data.json.readValue(payload.toString(),type);}catch(Exception e){throw new IllegalStateException("AI proposal payload invalid",e);}}
 public Object confirm(AuthService.Session s,UUID id,ConfirmInput i,UUID trace){return b.tx.execute(st->{var a=actor(s);var draft=proposal(a,id);ai.readRun(s,(UUID)draft.get("runId"));if(!Crypto.hash(i.confirmationToken()).equals(draft.get("confirmationHash")))throw ApiError.conflict("业务保存确认无效");if("APPLIED".equals(draft.get("status")))return map("id",id,"status","APPLIED","resultId",draft.get("resultId"),"replayed",true);if(!"DRAFT".equals(draft.get("status"))||number(draft,"version")!=i.expectedVersion()||!((Instant)draft.get("expiresAt")).isAfter(Instant.now()))throw ApiError.conflict("草稿确认已过期或变化，请重新预览");eligible(s,a,(UUID)draft.get("runId"));UUID result;if("CREATE_LEAD".equals(draft.get("action"))){var lead=business.createLead(s,decode(draft.get("payload"),BusinessService.LeadCreate.class),"ai-proposal-"+id,trace);result=lead.id();}else{var activity=sales.createActivity(s,decode(draft.get("payload"),SalesService.ActivityCreate.class),"ai-proposal-"+id,trace);result=(UUID)activity.get("id");}b.db.update("UPDATE crm_ai_proposal SET status='APPLIED',result_id=:result,version=version+1,applied_at=now() WHERE tenant_id=:tenant AND id=:id AND status='DRAFT'",map("result",result,"tenant",a.tenant().id(),"id",id));b.audit(a,"AI_PROPOSAL_APPLIED","AI_PROPOSAL",id,i.expectedVersion()+1,trace);return map("id",id,"status","APPLIED","resultId",result,"replayed",false);});}
 public Object cancel(AuthService.Session s,UUID id,long version,UUID trace){return b.tx.execute(st->{var a=actor(s);var draft=proposal(a,id);ai.readRun(s,(UUID)draft.get("runId"));if(!"DRAFT".equals(draft.get("status"))||number(draft,"version")!=version)throw ApiError.conflict("草稿状态已变化");b.db.update("UPDATE crm_ai_proposal SET status='CANCELLED',version=version+1 WHERE tenant_id=:tenant AND id=:id",map("tenant",a.tenant().id(),"id",id));b.audit(a,"AI_PROPOSAL_CANCELLED","AI_PROPOSAL",id,version+1,trace);return map("cancelled",true);});}
}
